import pandas as pd

try:
    # Load the Excel file
    file_path = 'nasa_budget_incomplete.xlsx'
    xls = pd.ExcelFile(file_path)

    print(f"Sheet names: {xls.sheet_names}")

    for sheet_name in xls.sheet_names:
        print(f"\n--- Sheet: {sheet_name} ---")
        df = pd.read_excel(xls, sheet_name=sheet_name)

        # Check for '???' in the dataframe
        # We convert to string to ensure we catch '???' even if mixed types exist
        # But '???' usually makes the column object type

        missing_locations = []
        for index, row in df.iterrows():
            for col in df.columns:
                if str(row[col]) == '???':
                    missing_locations.append((index, col))

        if missing_locations:
            print(f"Found '???' at:")
            for idx, col in missing_locations:
                print(f"  Row {idx}, Column '{col}'")
                # Print context
                print(f"  Row content: {row.to_dict()}")
        else:
            print("No '???' found in this sheet.")

        print(f"Head of {sheet_name}:")
        print(df.head())
        print(f"Columns: {df.columns.tolist()}")

except Exception as e:
    print(f"Error: {e}")
